const ProjectView: React.FC = () => {
  const { projectId, view } = useParams<{ projectId: string, view: ViewType }>();
  const { state, dispatch, syncToCloud } = useProjects();
  const navigate = useNavigate(); 
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isCelebrating, setIsCelebrating] = useState(false);

  const [activeReminders, setActiveReminders] = useState<Task[]>([]);

  const findProject = useCallback((id: string, list: Project[]): Project | null => {
    for (const p of list) {
      if (p.id === id) return p;
      const found = findProject(id, p.children);
      if (found) return found;
    }
    return null;
  }, []);

  const currentProject = useMemo(() => {
    return (projectId ? findProject(projectId, state.projects) : null) || state.projects[0];
  }, [projectId, state.projects, findProject]);

  const activeView = (view || 'dashboard') as ViewType;

  const getAggregatedTasks = useCallback((proj: Project): Task[] => {
    let tasks = [...proj.tasks];
    proj.children.forEach(child => {
      tasks = [...tasks, ...getAggregatedTasks(child)];
    });
    return tasks;
  }, []);

  const aggregatedTasks = useMemo(() => {
    return currentProject ? getAggregatedTasks(currentProject) : [];
  }, [currentProject, getAggregatedTasks]);

  // ---------------------------------------------------------
  // 🍓 Melody 提醒引擎
  // ---------------------------------------------------------
  useEffect(() => {
    const checkReminders = () => {
      const now = new Date();
      const todayStr = format(now, 'yyyy-MM-dd');
      const foundAlerts: Task[] = [];
      const updatedTaskIds: {id: string, history: string[]}[] = [];

      console.log(`[Melody 提醒引擎] 正在掃描任務... ${format(now, 'HH:mm:ss')}`);

      aggregatedTasks.forEach(task => {
        if (task.status === TaskStatus.COMPLETED || !task.reminder || task.reminder.type === 'none') return;

        const history = task.remindedHistory || [];
        let triggered = false;
        let triggeredKey = '';

        if (task.reminder.type === 'custom' && task.reminder.date) {
          const reminderDate = new Date(task.reminder.date);
          if (now >= reminderDate && !history.includes('custom_fired')) {
            triggered = true;
            triggeredKey = 'custom_fired';
          }
        }

        if (task.reminder.type === '1_day' || task.reminder.type === '3_days') {
          const days = task.reminder.type === '1_day' ? 1 : 3;
          const dueDate = new Date(task.endDate);
          const triggerDate = new Date(addDays(dueDate, -days).setHours(0, 0, 0, 0));
          const historyKey = `${todayStr}_${task.reminder.type}`;

          if (now >= triggerDate && !history.includes(historyKey)) {
            triggered = true;
            triggeredKey = historyKey;
          }
        }

        if (triggered) {
          foundAlerts.push(task);
          updatedTaskIds.push({ id: task.id, history: [...history, triggeredKey] });

          if (Notification.permission === 'granted') {
            new Notification(`🎀 Melody 提醒：${task.title}`, {
              body: `任務時間到囉！快來處理吧 🍰`,
              icon: '/vite.svg',
            });
          }
        }
      });

      if (foundAlerts.length > 0) {
        setActiveReminders(prev => [...prev, ...foundAlerts]);
        updatedTaskIds.forEach(item => {
          updateTask(item.id, { remindedHistory: item.history });
        });
      }
    };

    checkReminders();
    const interval = setInterval(checkReminders, 10000);
    return () => clearInterval(interval);
  }, [aggregatedTasks]);

  const updateProject = (id: string, updates: Partial<Project>) => {
    const updater = (list: Project[]): Project[] => list.map(p => {
      if (p.id === id) return { ...p, ...updates };
      return { ...p, children: updater(p.children) };
    });
    const next = updater(state.projects);
    dispatch({ type: 'UPDATE_PROJECTS', projects: next });
    syncToCloud(next);
  };

  const deleteProject = (id: string) => {
    if (!confirm('😱 確定要刪除整個計畫嗎？\n所有子計畫與任務也會一起消失喔！🍭')) return;
    const remover = (list: Project[]): Project[] => list.filter(p => p.id !== id).map(p => ({
      ...p,
      children: remover(p.children)
    }));
    const next = remover(state.projects);
    dispatch({ type: 'UPDATE_PROJECTS', projects: next });
    syncToCloud(next);
    if (next.length > 0) navigate(`/project/${next[0].id}/dashboard`);
    else navigate('/');
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    const updater = (list: Project[]): Project[] => list.map(p => {
      const idx = p.tasks.findIndex(t => t.id === taskId);
      if (idx !== -1) {
        const ts = [...p.tasks];
        ts[idx] = { ...ts[idx], ...updates };
        return { ...p, tasks: ts };
      }
      return { ...p, children: updater(p.children) };
    });
    const next = updater(state.projects);
    dispatch({ type: 'UPDATE_PROJECTS', projects: next });
    syncToCloud(next);
  };

  const addTask = () => {
    if (!currentProject) return;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      title: '新任務 🎀',
      description: '',
      startDate: today.toISOString(),
      endDate: addDays(today, 2).toISOString(),
      progress: 0,
      status: TaskStatus.TODO,
      priority: TaskPriority.MEDIUM,
      color: COLORS.taskColors[Math.floor(Math.random() * COLORS.taskColors.length)],
      attachments: [],
      tags: [],
      remindedHistory: []
    };
    updateProject(currentProject.id, { tasks: [...currentProject.tasks, newTask] });
    setEditingTaskId(newTask.id);
  };

  const deleteTask = (taskId: string) => {
    if (!confirm('確定要刪除這個任務嗎？ 🍬')) return;
    const remover = (list: Project[]): Project[] => list.map(p => ({
      ...p,
      tasks: p.tasks.filter(t => t.id !== taskId),
      children: remover(p.children)
    }));
    const next = remover(state.projects);
    dispatch({ type: 'UPDATE_PROJECTS', projects: next });
    syncToCloud(next);
  };

  const addProject = (parentId: string | null) => {
    const newP: Project = {
      id: Math.random().toString(36).substr(2, 9),
      name: '新計畫 🎀',
      parentId,
      notes: '',
      precautions: [],
      precautionsColor: COLORS.stickyNotes[Math.floor(Math.random() * COLORS.stickyNotes.length)],
      tasks: [],
      children: [],
      logoUrl: '📁',
      attachments: []
    };
    let next: Project[];
    if (!parentId) next = [...state.projects, newP];
    else {
      const updater = (list: Project[]): Project[] => list.map(p => {
        if (p.id === parentId) return { ...p, children: [...p.children, newP] };
        return { ...p, children: updater(p.children) };
      });
      next = updater(state.projects);
    }
    dispatch({ type: 'UPDATE_PROJECTS', projects: next });
    syncToCloud(next);
    navigate(`/project/${newP.id}/dashboard`);
  };

  const handleLogin = async () => {
    if (!isConfigured || !auth) return;
    try { await signInWithPopup(auth, googleProvider); } catch (e) { console.error(e); }
  };

  if (state.isLoading) return (
    <div className="h-screen flex items-center justify-center bg-[#fff5f8] dark:bg-kuromi-bg">
      <Loader2 className="w-12 h-12 text-pink-400 animate-spin" />
    </div>
  );

  return (
    <div className="flex min-h-screen relative overflow-x-hidden bg-[#fff5f8] dark:bg-kuromi-bg transition-colors duration-500">
      {isSidebarOpen && <div className="fixed inset-0 bg-pink-900/20 backdrop-blur-sm z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}
      {isCelebrating && <Celebration />}
      {activeReminders.length > 0 && <ReminderPopup tasks={activeReminders} onClose={() => setActiveReminders([])} />}

      <Sidebar 
        projects={state.projects} 
        workspaceLogo={state.workspaceLogo}
        workspaceName={state.workspaceName}
        onUpdateWorkspace={(logo, name) => {
          dispatch({ type: 'UPDATE_WORKSPACE', logo, name });
          syncToCloud(state.projects, logo, name);
        }}
        selectedProjectId={currentProject.id} 
        isOpen={isSidebarOpen}
        onSelectProject={(id) => { 
          navigate(`/project/${id}/${activeView}`);
          if (window.innerWidth < 768) setIsSidebarOpen(false); 
        }}
        onAddProject={addProject}
      />

      <main className="flex-1 p-4 md:p-8 overflow-y-auto max-h-screen custom-scrollbar transition-all duration-300">
        <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-6">
          <div className="flex items-center gap-3 md:gap-6 group">
            <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 text-pink-500 bg-white dark:bg-kuromi-card rounded-xl shadow-sm border border-pink-100 dark:border-gray-700">
              <Menu size={24} />
            </button>
            <div className="relative cursor-pointer group" onClick={() => {
              const res = prompt('請輸入 Emoji 或圖片網址 🍭', currentProject.logoUrl || '📁');
              if (res !== null) updateProject(currentProject.id, { logoUrl: res });
            }}>
              <div className="w-12 h-12 md:w-20 md:h-20 bg-white dark:bg-kuromi-card rounded-2xl md:rounded-[32px] flex items-center justify-center text-2xl md:text-5xl shadow-inner border-2 border-pink-100 dark:border-gray-600 overflow-hidden">
                {currentProject.logoUrl?.startsWith('http') || currentProject.logoUrl?.startsWith('blob') ? <img src={currentProject.logoUrl} className="w-full h-full object-cover" /> : (currentProject.logoUrl || '📁')}
              </div>
              <div className="absolute -bottom-1 -right-1 bg-pink-500 p-1.5 rounded-full shadow-md border-2 border-white transition-transform group-hover:scale-110"><Edit3 size={12} className="text-white" /></div>
            </div>
            <div className="flex-1 min-w-0">
              <input value={currentProject.name} onChange={(e) => updateProject(currentProject.id, { name: e.target.value })} className="text-2xl md:text-4xl font-black text-pink-600 dark:text-kuromi-text bg-transparent border-none focus:outline-none focus:ring-2 focus:ring-pink-100 rounded-xl px-2 w-full truncate" />
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => setIsSearchOpen(true)} className="p-2.5 bg-white dark:bg-kuromi-card text-pink-400 dark:text-kuromi-text hover:text-pink-600 rounded-xl border border-pink-50 dark:border-gray-700 shadow-sm hover:bg-pink-50 transition-all flex items-center gap-2"><Search size={20} /> <span className="hidden sm:inline font-bold text-sm">搜尋</span></button>

            <button 
              onClick={() => deleteProject(currentProject.id)} 
              className="p-2.5 bg-white dark:bg-kuromi-card text-pink-200 hover:text-red-500 rounded-xl border border-pink-50 dark:border-gray-700 shadow-sm transition-all"
              title="刪除整個計畫"
            >
              <Trash2 size={20} />
            </button>

            {!state.user ? (
              <button onClick={handleLogin} className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl font-bold text-sm shadow-md border border-blue-50 transition-all text-blue-500 hover:bg-blue-50 active:scale-95"><LogIn size={18} /> Google 登入</button>
            ) : (
              <div className="flex items-center gap-3 bg-white/60 dark:bg-kuromi-card p-1.5 pr-4 rounded-2xl border border-pink-100 dark:border-gray-700 shadow-sm">
                <img src={state.user.photoURL || ''} className="w-8 h-8 rounded-full border-2 border-pink-200 shadow-sm" />
                <button onClick={() => auth && signOut(auth)} className="text-[10px] font-bold text-pink-300 hover:text-red-400">登出</button>
              </div>
            )}
            <button onClick={() => addProject(currentProject.id)} className="flex items-center gap-2 bg-pink-500 text-white px-4 md:px-6 py-2 rounded-xl md:rounded-2xl font-bold text-xs md:text-sm shadow-md hover:bg-pink-600 transition-all active:scale-95"><Plus size={16} /> 建立計畫</button>
          </div>
        </header>

        <div className="flex gap-2 md:gap-4 mb-8 overflow-x-auto pb-2 no-scrollbar">
          {[
            { id: 'dashboard', label: '總覽', icon: <LayoutDashboard size={18} /> },
            { id: 'kanban', label: '看板', icon: <LayoutGrid size={18} /> },
            { id: 'gantt', label: '甘特圖', icon: <BarChart2 size={18} /> },
            { id: 'calendar', label: '日期表', icon: <Calendar size={18} /> },
            { id: 'notes', label: '設定', icon: <BookOpen size={18} /> },
          ].map(v => (
            <button key={v.id} onClick={() => navigate(`/project/${currentProject.id}/${v.id}`)} className={`flex items-center gap-2 px-5 md:px-8 py-2 md:py-3 rounded-xl md:rounded-[20px] font-bold transition-all ${activeView === v.id ? 'bg-pink-500 text-white shadow-xl translate-y-[-2px]' : 'text-pink-300 bg-white/50 dark:bg-white/5 hover:bg-pink-50 dark:hover:bg-white/10'}`}>
              {v.icon} {v.label}
            </button>
          ))}
        </div>

        <div className="space-y-8 md:space-y-12 pb-20 animate-in fade-in duration-500">
          {activeView === 'dashboard' ? (
            <div className="space-y-8 md:space-y-12">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-stretch">
                <ProgressBoard tasks={aggregatedTasks} />
                <ProjectPrecautions 
                  precautions={currentProject.precautions || []} 
                  backgroundColor={currentProject.precautionsColor}
                  onUpdate={(items) => updateProject(currentProject.id, { precautions: items })} 
                  onColorChange={(color) => updateProject(currentProject.id, { precautionsColor: color })}
                />
              </div>

              <GanttChart tasks={aggregatedTasks} onTaskClick={setEditingTaskId} />

              <div className="bg-white dark:bg-kuromi-card rounded-[32px] md:rounded-[40px] p-6 md:p-8 cute-shadow border border-pink-100 dark:border-gray-700">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
                  <h3 className="text-xl font-bold text-pink-600 dark:text-kuromi-accent flex items-center gap-3"><span className="p-2 bg-pink-100 dark:bg-gray-700 rounded-xl text-pink-500"><Check size={20} /></span>任務清單</h3>
                  <button onClick={addTask} className="w-full sm:w-auto flex items-center justify-center gap-2 bg-pink-50 dark:bg-gray-700 text-pink-500 dark:text-pink-300 px-6 py-2.5 rounded-2xl font-bold hover:bg-pink-100 dark:hover:bg-gray-600 shadow-sm transition-all"><Plus size={18} /> 新增任務</button>
                </div>
                <div className="space-y-4">
                  {aggregatedTasks.length > 0 ? (
                    aggregatedTasks.map(task => (
                      <TaskItem 
                        key={task.id} 
                        task={task} 
                        onToggleStatus={() => {
                          const s = task.status === TaskStatus.COMPLETED ? TaskStatus.TODO : TaskStatus.COMPLETED;
                          updateTask(task.id, { status: s, progress: s === TaskStatus.COMPLETED ? 100 : 0 });
                        }}
                        onEdit={() => setEditingTaskId(task.id)}
                        onDelete={() => deleteTask(task.id)}
                      />
                    ))
                  ) : (
                    <div className="text-center py-12 text-pink-200 dark:text-gray-500 font-bold italic border-2 border-dashed border-pink-50 dark:border-gray-700 rounded-3xl">快來新增你的第一個任務吧！🍭</div>
                  )}
                </div>
              </div>

              {/* 🍓 恢復日期表顯示 */}
              <CalendarView tasks={aggregatedTasks} />
            </div>
          ) : (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full">
              {activeView === 'kanban' && <KanbanBoard tasks={aggregatedTasks} onTaskUpdate={updateTask} onTaskClick={setEditingTaskId} />}
              {activeView === 'gantt' && <GanttChart tasks={aggregatedTasks} onTaskClick={setEditingTaskId} />}
              {activeView === 'calendar' && <CalendarView tasks={aggregatedTasks} />}
              {activeView === 'notes' && (
                <NotesArea 
                  notes={currentProject.notes} 
                  logoUrl={currentProject.logoUrl} 
                  attachments={currentProject.attachments}
                  onUpdateNotes={(notes) => updateProject(currentProject.id, { notes })} 
                  onUpdateLogo={(url) => updateProject(currentProject.id, { logoUrl: url })} 
                  onUpdateAttachments={(files) => updateProject(currentProject.id, { attachments: files })}
                />
              )}
            </div>
          )}
        </div>
      </main>

      {isSearchOpen && (
        <SearchPalette 
          projects={state.projects} 
          onClose={() => setIsSearchOpen(false)} 
          onSelect={(id) => {
            navigate(`/project/${id}/dashboard`);
            setIsSearchOpen(false);
          }}
        />
      )}

      {editingTaskId && aggregatedTasks.find(t => t.id === editingTaskId) && (
        <TaskDetailModal 
          task={aggregatedTasks.find(t => t.id === editingTaskId)!}
          allProjects={state.projects}
          onClose={() => setEditingTaskId(null)}
          onUpdate={(up) => updateTask(editingTaskId, up)}
        />
      )}
    </div>
  );
};

const App: React.FC = () => {
  const { state } = useProjects();
  return (
    <Routes>
      <Route path="/project/:projectId/:view" element={<ProjectView />} />
      <Route
        path="/"
        element={
          state.projects.length > 0 ? (
            <Navigate to={`/project/${state.projects[0].id}/dashboard`} replace />
          ) : (
            <div className="h-screen flex items-center justify-center bg-[#fff5f8] dark:bg-kuromi-bg">
              <Loader2 className="w-12 h-12 text-pink-400 animate-spin" />
            </div>
          )
        }
      />
    </Routes>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Calendar, Flag, AlignLeft, CheckCircle2, Eye, Edit3, Link as LinkIcon, ExternalLink, Trash2, Plus, Globe, ImageIcon, Save, Tag, Check, Palette, Bell, Clock, Activity, Send, CheckSquare } from 'lucide-react';
import { Task, TaskPriority, TaskStatus, Project, Attachment, ResourceCategory, TaskTag, ReminderType, TaskReminder } from '../types.ts';
import { COLORS, TAG_PALETTE } from '../constants.tsx';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { format } from 'date-fns';

interface TaskDetailModalProps {
  task: Task;
  allProjects: Project[];
  onClose: () => void;
  onUpdate: (updates: Partial<Task>) => void;
}

export const TaskDetailModal: React.FC<TaskDetailModalProps> = ({ task, onClose, onUpdate }) => {
  const [isEditingDesc, setIsEditingDesc] = useState(false);
  const [showPreviewDuringEdit, setShowPreviewDuringEdit] = useState(false);
  const [tempDesc, setTempDesc] = useState(task.description || '');

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_PALETTE[Math.floor(Math.random() * TAG_PALETTE.length)]);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  // 🍓 提醒狀態暫存
  const [tempReminder, setTempReminder] = useState<TaskReminder>(task.reminder || { type: 'none' });

  const [permissionState, setPermissionState] = useState(
    'Notification' in window ? Notification.permission : 'default'
  );

  useEffect(() => {
    setTempDesc(task.description || '');
    setIsEditingDesc(false);
    setTempReminder(task.reminder || { type: 'none' });
  }, [task.id]);

  const handleStartEdit = () => {
    setTempDesc(task.description || '');
    setIsEditingDesc(true);
    setShowPreviewDuringEdit(false);
  };

  const handleSaveDesc = () => {
    onUpdate({ description: tempDesc });
    setIsEditingDesc(false);
  };

  const handleCancelEdit = () => {
    setTempDesc(task.description || '');
    setIsEditingDesc(false);
  };

  const handleAddLink = () => {
    const name = prompt("🍓 連結標題");
    if (!name) return;
    const url = prompt("🌐 請貼上網址");
    if (!url) return;

    let category: ResourceCategory = 'link';
    if (url.match(/\.(jpeg|jpg|gif|png|webp)$/) != null) category = 'image';
    else if (url.includes('docs.google.com')) category = 'document';

    const newAttachment: Attachment = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      url,
      category,
      createdAt: new Date().toISOString()
    };
    onUpdate({ attachments: [...(task.attachments || []), newAttachment] });
  };

  const handleAddTag = () => {
    const tagName = tagInput.trim();
    if (!tagName) return;
    const currentTags = task.tags || [];
    if (!currentTags.some(t => t.name === tagName)) {
      onUpdate({ tags: [...currentTags, { name: tagName, color: selectedTagColor }] });
    }
    setTagInput('');
    setSelectedTagColor(TAG_PALETTE[Math.floor(Math.random() * TAG_PALETTE.length)]);
  };

  const handleRemoveTag = (tagNameToRemove: string) => {
    onUpdate({ tags: (task.tags || []).filter(t => t.name !== tagNameToRemove) });
  };

  // ⏰ 提醒設定處理 (僅暫存)
  const handleReminderTypeChange = (type: ReminderType) => {
    if (type === 'custom') {
      const now = new Date();
      now.setHours(now.getHours() + 1);
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      const day = String(now.getDate()).padStart(2, '0');
      const hours = String(now.getHours()).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const defaultIso = `${year}-${month}-${day}T${hours}:${minutes}`;
      setTempReminder({ type, date: defaultIso });
    } else {
      setTempReminder({ type });
    }
  };

  // ⏰ 點下「記錄提醒」才真正儲存
  const saveReminderToSchedule = () => {
    if (tempReminder.type === 'none') {
      // 若不提醒，清除設定與歷史，釋放排程
      onUpdate({ reminder: { type: 'none' }, remindedHistory: [] });
      alert('已取消該任務的所有提醒排程 🔕');
    } else {
      // 存入設定並重置歷史紀錄，讓引擎重新讀取
      onUpdate({ reminder: tempReminder, remindedHistory: [] });
      alert(`已將「${task.title}」成功加入提醒排程！🍰`);
    }
  };

  const requestNotificationPermission = async () => {
    if (!('Notification' in window)) return;
    const permission = await Notification.requestPermission();
    setPermissionState(permission);
  };

  const sendTestNotification = () => {
    if (Notification.permission === 'granted') {
        new Notification('🔔 測試成功！', {
            body: `這是來自任務「${task.title}」的測試通知，這樣表示設定沒問題囉！`,
            icon: '/vite.svg'
        });
    } else {
        requestNotificationPermission();
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex justify-end bg-black/20 dark:bg-black/50 backdrop-blur-sm animate-in fade-in duration-300" onClick={onClose}>
      <div className="w-full max-w-lg bg-white dark:bg-kuromi-card h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-500 rounded-l-[40px] border-l-4 border-pink-100 dark:border-gray-600" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between p-8 border-b border-pink-50 dark:border-gray-700">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl flex items-center justify-center text-xl shadow-inner bg-pink-50 dark:bg-gray-700">🍭</div>
            <h2 className="text-xl font-bold text-pink-600 dark:text-kuromi-accent">任務詳情</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-pink-50 dark:hover:bg-white/10 rounded-full transition-colors text-pink-300 dark:text-gray-400"><X size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
          <div className="space-y-2">
            <label className="text-xs font-bold text-pink-300 dark:text-gray-500 uppercase tracking-wider">任務名稱</label>
            <input value={task.title} onChange={(e) => onUpdate({ title: e.target.value })} className="text-2xl font-bold text-[#5c4b51] dark:text-kuromi-text w-full bg-pink-50/20 dark:bg-white/5 border-2 border-transparent focus:border-pink-100 dark:focus:border-gray-600 rounded-2xl px-3 py-2 transition-all" />
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-pink-300 dark:text-gray-500 flex items-center gap-1 uppercase tracking-wider"><CheckCircle2 size={12} /> 狀態</label>
              <select value={task.status} onChange={(e) => onUpdate({ status: e.target.value as TaskStatus })} className="w-full p-3 rounded-2xl border-none text-sm font-bold text-[#5c4b51] shadow-sm cursor-pointer" style={{ backgroundColor: COLORS.status[task.status] + '66' }}>
                {Object.values(TaskStatus).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-pink-300 dark:text-gray-500 flex items-center gap-1 uppercase tracking-wider"><Flag size={12} /> 優先度</label>
              <select value={task.priority} onChange={(e) => onUpdate({ priority: e.target.value as TaskPriority })} className="w-full p-3 rounded-2xl border-none text-sm font-bold text-[#5c4b51] shadow-sm cursor-pointer" style={{ backgroundColor: COLORS.priority[task.priority] }}>
                {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>

          <div className="space-y-2 bg-white/50 dark:bg-white/5 p-4 rounded-2xl border border-pink-50 dark:border-gray-700 shadow-sm">
            <div className="flex justify-between items-center">
                <label className="text-xs font-bold text-pink-300 dark:text-gray-500 flex items-center gap-1 uppercase tracking-wider"><Activity size={14} /> 任務進度</label>
                <span className="text-sm font-black text-pink-500 bg-white dark:bg-gray-800 dark:text-pink-300 px-2 py-0.5 rounded-lg shadow-sm">{task.progress}%</span>
            </div>
            <input type="range" min="0" max="100" step="5" value={task.progress} onChange={(e) => onUpdate({ progress: parseInt(e.target.value) })} className="w-full h-2 bg-pink-100 dark:bg-gray-600 rounded-lg appearance-none cursor-pointer accent-pink-500" style={{ background: `linear-gradient(to right, #ff85b2 ${task.progress}%, transparent ${task.progress}%)` }} />
          </div>

          <div className="grid grid-cols-2 gap-6">
             <div className="space-y-2">
              <label className="text-xs font-bold text-pink-300 dark:text-gray-500 flex items-center gap-1 uppercase tracking-wider"><Calendar size={12} /> 開始日期</label>
              <input type="date" value={task.startDate.split('T')[0]} onChange={(e) => onUpdate({ startDate: new Date(e.target.value).toISOString() })} className="w-full p-4 rounded-[20px] border border-pink-100/50 dark:border-gray-700 text-sm font-bold text-[#5c4b51] dark:text-white bg-white dark:bg-[#1a1618] [color-scheme:dark]" />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-pink-300 dark:text-gray-500 flex items-center gap-1 uppercase tracking-wider"><Calendar size={12} /> 結束日期</label>
              <input type="date" value={task.endDate.split('T')[0]} onChange={(e) => onUpdate({ endDate: new Date(e.target.value).toISOString() })} className="w-full p-4 rounded-[20px] border border-pink-100/50 dark:border-gray-700 text-sm font-bold text-[#5c4b51] dark:text-white bg-white dark:bg-[#1a1618] [color-scheme:dark]" />
            </div>
          </div>

          {/* ⏰ 提醒設定增強 */}
          <div className="space-y-3 bg-blue-50/50 dark:bg-blue-900/20 p-4 rounded-2xl border border-blue-100 dark:border-blue-800">
            <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-blue-400 flex items-center gap-1 uppercase tracking-wider">
                  <Bell size={12} /> 任務提醒輔助
                  {permissionState !== 'granted' && (
                    <button className="text-[10px] bg-blue-100 dark:bg-blue-800 text-blue-500 dark:text-blue-200 px-2 py-0.5 rounded-md ml-2 font-bold" onClick={requestNotificationPermission}>開啟權限</button>
                  )}
                </label>
                <button onClick={sendTestNotification} className="flex items-center gap-1 text-[10px] bg-blue-400 text-white px-2 py-1 rounded-lg font-bold hover:bg-blue-500 transition-all shadow-sm">
                  <Send size={10} /> 測試
                </button>
            </div>

            <div className="flex flex-col gap-3">
              <div className="flex gap-2">
                <select 
                  value={tempReminder.type} 
                  onChange={(e) => handleReminderTypeChange(e.target.value as ReminderType)} 
                  className="flex-1 p-3 rounded-xl border border-blue-100 dark:border-blue-700 text-sm font-bold text-[#5c4b51] dark:text-gray-200 bg-white dark:bg-gray-800"
                >
                  <option value="none">🔕 不紀錄排程</option>
                  <option value="1_day">🗓️ 到期前 1 天</option>
                  <option value="3_days">🗓️ 到期前 3 天</option>
                  <option value="custom">⏰ 自訂精確時間</option>
                </select>

                <button 
                  onClick={saveReminderToSchedule}
                  className={`px-4 py-2 rounded-xl font-bold text-xs flex items-center gap-1.5 transition-all shadow-md active:scale-95 ${
                    tempReminder.type === 'none' 
                      ? 'bg-gray-100 dark:bg-gray-700 text-gray-500' 
                      : 'bg-blue-500 text-white hover:bg-blue-600'
                  }`}
                >
                  <CheckSquare size={14} /> 記錄提醒
                </button>
              </div>

              {tempReminder.type === 'custom' && (
                <div className="flex items-center gap-2 animate-in slide-in-from-top-2">
                  <Clock size={16} className="text-blue-300" />
