              <div className="flex flex-wrap gap-2">
                {task.tags?.map(tag => (
                  <span key={tag.name} className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold text-[#5c4b51]" style={{ backgroundColor: tag.color }}>
