                  title="選取標籤顏色"
                >
                  <Palette size={18} className="text-black/30" />
                </button>

                {/* 🍓 色票選單 */}
                {isPaletteOpen && (
                  <div className="absolute bottom-full left-0 mb-3 p-3 bg-white dark:bg-kuromi-card shadow-2xl rounded-2xl border border-pink-100 dark:border-gray-700 z-[70] grid grid-cols-4 gap-2 animate-in zoom-in-95">
                    {TAG_PALETTE.map(c => (
                      <button 
                        key={c} 
                        onClick={() => { setSelectedTagColor(c); setIsPaletteOpen(false); }} 
