                        style={{ backgroundColor: c }} 
                      />
                    ))}
                    <button 
                      onClick={() => colorInputRef.current?.click()}
                      className="w-8 h-8 rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center bg-gray-50 hover:bg-gray-100"
                    >
                      <Plus size={14} className="text-gray-400" />
                    </button>
                    <input 
