        {/* 🍓 過濾標籤區 (修復顏色、複選、清除) */}
        <div className="flex items-center gap-4 mb-8 overflow-x-auto pb-2 no-scrollbar px-2">
          <div className="flex items-center gap-2 text-pink-400 flex-shrink-0">
            <Filter size={18} />
            <span className="text-sm font-black">過濾標籤:</span>
          </div>
          <div className="flex gap-2">
            {selectedTags.length > 0 && (
              <button onClick={() => setSelectedTags([])} className="flex items-center gap-1.5 px-5 py-2 rounded-full text-xs font-black bg-pink-50 text-pink-400 border border-pink-100 hover:bg-pink-100 transition-all shadow-sm">
                <RotateCcw size={12} /> 清除全部
              </button>
            )}
            {uniqueTags.map(tagName => (
              <button 
                key={tagName}
                onClick={() => handleToggleTag(tagName)}
                className={`flex items-center gap-1.5 px-5 py-2 rounded-full text-xs font-black transition-all border shadow-sm ${selectedTags.includes(tagName) ? 'text-white scale-105 ring-2 ring-pink-200' : 'bg-gray-100/60 dark:bg-white/5 text-gray-500 dark:text-gray-400 border-transparent hover:bg-gray-200'}`}
                style={{ backgroundColor: selectedTags.includes(tagName) ? tagColorMap[tagName] : undefined, borderColor: selectedTags.includes(tagName) ? 'transparent' : undefined }}
              >
                <Tag size={12} /> {tagName}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-12 pb-20">
          {activeView === 'dashboard' ? (
            <div className="space-y-12">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-stretch">
                <ProgressBoard tasks={filteredTasks} />
                <ProjectPrecautions precautions={currentProject.precautions || []} onUpdate={(items) => updateProject(currentProject.id, { precautions: items })} onColorChange={(color) => updateProject(currentProject.id, { precautionsColor: color })} />
              </div>
              <GanttChart tasks={filteredTasks} onTaskClick={setEditingTaskId} />

              {/* 🍓 任務清單視覺修正 (如圖 2 & 3) */}
              <div className="bg-white dark:bg-kuromi-card rounded-[40px] p-8 cute-shadow border border-pink-100 dark:border-gray-700">
                <div className="flex items-center justify-between mb-8">
                   <div className="flex items-center gap-3">
                     <div className="w-10 h-10 bg-pink-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-pink-400 shadow-inner border border-pink-100 dark:border-gray-700"><Check size={20} /></div>
                     <h3 className="text-xl font-bold text-pink-600 dark:text-kuromi-accent">任務清單</h3>
                   </div>
                   <button onClick={addTask} className="flex items-center gap-2 px-5 py-2 rounded-2xl bg-pink-50 dark:bg-gray-800 text-pink-500 dark:text-pink-300 font-black text-xs hover:bg-pink-100 transition-all shadow-sm">
                     <Plus size={16} /> 新增任務
                   </button>
                </div>

                <div className="space-y-4">
                  {filteredTasks.map(task => (
                    <div key={task.id} onClick={() => setEditingTaskId(task.id)} className="flex items-center gap-4 p-5 rounded-[28px] bg-white dark:bg-white/5 border border-pink-50 dark:border-gray-800 hover:bg-pink-50/20 dark:hover:bg-white/10 hover:shadow-lg transition-all cursor-grab active:cursor-grabbing group">
                      <div className={`w-8 h-8 rounded-2xl border-2 flex-shrink-0 flex items-center justify-center transition-all ${task.status === TaskStatus.COMPLETED ? 'bg-pink-400 border-pink-400 text-white' : 'bg-pink-50/50 dark:bg-transparent border-pink-100'}`} onClick={(e) => { e.stopPropagation(); updateTask(task.id, { status: task.status === TaskStatus.COMPLETED ? TaskStatus.TODO : TaskStatus.COMPLETED, progress: task.status === TaskStatus.COMPLETED ? 0 : 100 }); }}>
                        {task.status === TaskStatus.COMPLETED && <Check size={18} strokeWidth={4} />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="font-black text-[#5c4b51] dark:text-gray-200 text-base group-hover:text-pink-600 truncate">{task.title}</div>
                        <div className="flex items-center gap-2 mt-1">
                          {task.tags?.map(tag => (
                            <span key={tag.name} className="px-2 py-0.5 rounded-lg text-[9px] font-black text-[#5c4b51]" style={{ backgroundColor: tag.color + 'aa' }}>#{tag.name}</span>
                          ))}
                          {shouldShowBell(task) && <Bell size={12} className="text-blue-400 fill-blue-400 animate-pulse" />}
                        </div>
                      </div>
                      <div className="flex items-center gap-4">
                        <div className={`hidden sm:flex px-3 py-1 rounded-xl text-[10px] font-black shadow-sm ${task.status === TaskStatus.COMPLETED ? 'bg-green-100 text-green-600' : task.status === TaskStatus.IN_PROGRESS ? 'bg-orange-100 text-orange-600' : 'bg-gray-100 text-gray-600'}`}>
                          {task.status}
                        </div>
                        <div className="text-lg font-black text-pink-500 w-12 text-right">{task.progress}%</div>
                        <button onClick={(e) => { e.stopPropagation(); if (confirm('確定要刪除這個任務嗎？ 🍬')) updateProject(currentProject.id, { tasks: currentProject.tasks.filter(t => t.id !== task.id) }); }} className="p-2 text-pink-100 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={18} /></button>
                      </div>
                    </div>
                  ))}
                  {filteredTasks.length === 0 && (
                    <div className="py-20 text-center text-pink-200 dark:text-gray-600 font-bold italic">目前沒有符合條件的任務喔 🍰</div>
                  )}
                </div>
              </div>
              <CalendarView tasks={filteredTasks} />
            </div>
          ) : (
            <div className="animate-in fade-in duration-500 h-full">
              {activeView === 'kanban' && <KanbanBoard tasks={filteredTasks} onTaskUpdate={updateTask} onTaskClick={setEditingTaskId} />}
              {activeView === 'gantt' && <GanttChart tasks={filteredTasks} onTaskClick={setEditingTaskId} />}
              {activeView === 'calendar' && <CalendarView tasks={filteredTasks} />}
              {activeView === 'notes' && <NotesArea notes={currentProject.notes} onUpdateNotes={(notes) => updateProject(currentProject.id, { notes })} onUpdateLogo={(url) => updateProject(currentProject.id, { logoUrl: url })} onUpdateAttachments={(files) => updateProject(currentProject.id, { attachments: files })} />}
            </div>
          )}
        </div>
      </main>
      {isSearchOpen && <SearchPalette projects={state.projects} onClose={() => setIsSearchOpen(false)} onSelect={(id) => { navigate(`/project/${id}/dashboard`); setIsSearchOpen(false); }} />}
      {editingTaskId && aggregatedTasks.find(t => t.id === editingTaskId) && (
        <TaskDetailModal 
          task={aggregatedTasks.find(t => t.id === editingTaskId)!} allProjects={state.projects}
          onClose={() => setEditingTaskId(null)} onUpdate={(up) => updateTask(editingTaskId, up)}
        />
      )}
    </div>
  );
};

