                      <div className="flex-1 min-w-0">
                        <div className="font-black text-[#5c4b51] dark:text-gray-200 text-base group-hover:text-pink-600 truncate">{task.title}</div>
                        <div className="flex items-center gap-2 mt-1">
                          {task.tags?.map(tag => (
                            <span key={tag.name} className="px-2 py-0.5 rounded-lg text-[9px] font-black text-[#5c4b51] dark:text-gray-300" style={{ backgroundColor: state.isDarkMode ? tag.color + '88' : tag.color + 'aa' }}>#{tag.name}</span>
