                  key={tagName} 
                  onClick={() => handleToggleTag(tagName)} 
                  className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-xs font-black transition-all border shadow-sm flex-shrink-0 ${isSelected ? 'scale-105 ring-2 ring-pink-100 dark:ring-pink-900/40 border-transparent text-black' : 'bg-gray-100/60 dark:bg-white/5 text-gray-500 dark:text-gray-400 border-transparent'}`} 
                  style={{ 
                    backgroundColor: isSelected ? tagColor : undefined,
                  }}
                  onMouseEnter={(e) => {
                    if (!isSelected) {
                      e.currentTarget.style.backgroundColor = tagColor + '44'; // Hover 時預覽顏色 (25% 透明度)
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (!isSelected) {
                      e.currentTarget.style.backgroundColor = ""; 
                    }
                  }}
                >
                  <Tag 
                    size={12} 
                    className={isSelected ? 'text-black' : ''} 
                    fill={isSelected ? "currentColor" : "none"} 
                  /> 
                  {tagName} 
                  {isSelected && <Check size={10} />}
                </button>
              );
            })}

            {/* 🍓 清除按鈕貼合在標籤最右邊 (如圖 1) */}
            {selectedTags.length > 0 && (
              <button 
                onClick={() => setSelectedTags([])} 
                className="flex items-center gap-1 px-4 py-2 rounded-full text-xs font-black bg-[#2d333b] dark:bg-[#3d444d] text-white hover:bg-[#444c56] transition-all shadow-sm flex-shrink-0"
              >
